<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { ClasificacionCuentaFlujo, TipoFlujoCuenta } from '../interfaces/cuenta-tesoreria.interface'
import { asignarTipoFlujoCaja, listarClasificacionFlujoCaja } from '../services/cuenta-tesoreria'
const rows = ref<ClasificacionCuentaFlujo[]>([]), search = ref(''), type = ref(''), loading = ref(false), error = ref(''), success = ref(''), selected = ref<ClasificacionCuentaFlujo | null>(null), selectedType = ref<TipoFlujoCuenta>('')
const filtered = computed(() => { const q = search.value.toLocaleUpperCase(); return rows.value.filter(x => (!q || `${x.cta_contable} ${x.descripcion}`.toLocaleUpperCase().includes(q)) && (!type.value || (type.value === 'N' ? !x.tipo_flujo_caja : x.tipo_flujo_caja === type.value))) })
const totals = computed(() => ({ ingresos: rows.value.filter(x => x.tipo_flujo_caja === 'I').length, egresos: rows.value.filter(x => x.tipo_flujo_caja === 'E').length, pendientes: rows.value.filter(x => !x.tipo_flujo_caja).length }))
const message = (e: unknown) => e instanceof Error ? e.message : 'No se pudo completar la operación.'
async function load() { loading.value = true; error.value = ''; try { rows.value = await listarClasificacionFlujoCaja() } catch (e) { error.value = message(e) } finally { loading.value = false } }
function configure(item: ClasificacionCuentaFlujo) { selected.value = item; selectedType.value = item.tipo_flujo_caja || '' }
async function save() { if (!selected.value || !confirm('¿Desea actualizar la clasificación de flujo de caja?')) return; loading.value = true; error.value = ''; try { await asignarTipoFlujoCaja(selected.value.id, selectedType.value); success.value = 'Clasificación actualizada correctamente.'; selected.value = null; await load() } catch (e) { error.value = message(e) } finally { loading.value = false } }
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Clasificación para flujo de caja</nav><header class="hero"><div class="mark">IE</div><div><small>MIA · FINANZAS · CONFIGURACIÓN</small><h1>Clasificación para flujo de caja</h1><p>Establece las cuentas contables de ingreso y egreso utilizadas en el flujo de caja.</p></div><strong>{{rows.length}} cuentas de nivel 1</strong></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><section class="summary"><article class="income"><small>INGRESOS</small><b>{{totals.ingresos}}</b></article><article class="expense"><small>EGRESOS</small><b>{{totals.egresos}}</b></article><article class="pending"><small>NO CONFIGURADAS</small><b>{{totals.pendientes}}</b></article></section><section class="filters"><input v-model.trim="search" placeholder="Buscar cuenta o descripción"><select v-model="type"><option value="">Todas las clasificaciones</option><option value="I">Ingresos</option><option value="E">Egresos</option><option value="N">No configuradas</option></select><button class="soft" @click="search='';type=''">Limpiar</button></section><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!filtered.length" class="empty">No se encontraron cuentas contables de nivel 1.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Cuenta</th><th>Descripción</th><th>Nivel</th><th>Naturaleza</th><th>Tipo flujo de caja</th><th>Estado</th><th>Acción</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td>{{item.id}}</td><td><b>{{item.cta_contable}}</b></td><td>{{item.descripcion}}</td><td>{{item.nivel}}</td><td>{{item.naturaleza_label||'-'}}</td><td><span :class="item.tipo_flujo_caja==='I'?'good':item.tipo_flujo_caja==='E'?'bad':'neutral'">{{item.tipo_flujo_caja==='I'?'INGRESO':item.tipo_flujo_caja==='E'?'EGRESO':'NO CONFIGURADO'}}</span></td><td><span :class="item.activa?'good':'bad'">{{item.activa?'ACTIVA':'INACTIVA'}}</span></td><td><button @click="configure(item)">Configurar</button></td></tr></tbody></table></div></section><div v-if="selected" class="backdrop" @mousedown.self="selected=null"><form class="dialog" @submit.prevent="save"><header><div><small>CONFIGURAR FLUJO DE CAJA</small><h2>{{selected.cta_contable}}</h2></div><button type="button" @click="selected=null">×</button></header><dl><dt>Descripción</dt><dd>{{selected.descripcion}}</dd><dt>Nivel</dt><dd>{{selected.nivel}}</dd><dt>Naturaleza</dt><dd>{{selected.naturaleza_label||'-'}}</dd></dl><label>Clasificación<select v-model="selectedType"><option value="">No configurado</option><option value="I">Cuenta de ingreso</option><option value="E">Cuenta de egreso</option></select></label><footer><button type="button" class="soft" @click="selected=null">Cancelar</button><button :disabled="loading">Guardar clasificación</button></footer></form></div></div></template>
<style scoped>
