g:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(520px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.dialog dl{display:grid;grid-template-columns:1fr 2fr;margin:0;font-size:.51rem}.dialog dt,.dialog dd{margin:0;padding:9px;border-bottom:1px solid #e2e9eb}.dialog dt{font-weight:700;background:#f2f6f7}.dialog label{display:grid;gap:5px;margin:15px 0;font-size:.52rem;font-weight:700}.dialog footer{display:flex;justify-content:center;gap:8px}@media(max-width:650px){.filters,.summary{grid-template-columns:1fr}.hero{flex-wrap:wrap}.mark{display:none}}
